async function requestTestnetFaucet(recipient, fetchImpl = defaultFetch) {
  const body = JSON.stringify({ FixedAmountRequest: { recipient } });
  let last = { ok: false, detail: "no faucet endpoint reachable" };
  for (const endpoint of FAUCET_ENDPOINTS) {
    try {
      const res = await fetchImpl(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body,
        signal: AbortSignal.timeout(15e3)
      });
      if (res.ok) return { ok: true, endpoint, status: res.status };
      const text = await res.text().catch(() => "");
      last = { ok: false, endpoint, status: res.status, detail: text.slice(0, 300) };
      if (res.status !== 404) return last;
    } catch (e) {
      last = { ok: false, endpoint, detail: errorMessage(e) };
    }
  }
  return last;
}
function setupTool(sdk, fetchImpl = defaultFetch) {
  return {
    name: "system_setup",
    description: "First-run setup: report this agent's Sui address, network and SUI balance; on testnet with under 0.05 SUI, request gas from the faucet. Every message costs a small gas fee, so run this before creating or joining channels and share the address with collaborators.",
    schema: EmptyArgs,
    handler: async () => {
      const address = sdk.keypair.toSuiAddress();
      const { network } = sdk.config;
      const readMist = async () => Number((await sdk.client.core.getBalance({ owner: address })).balance.balance);
      let mist = await readMist();
      let faucet;
      if (network === "testnet" && mist < MIN_BALANCE_MIST) {
        faucet = await requestTestnetFaucet(address, fetchImpl);
        if (faucet.ok) mist = await readMist().catch(() => mist);
      }
      const funded = mist >= MIN_BALANCE_MIST;
      const web_faucet = webFaucetUrl(address);
      const next_steps = funded ? "Ready. Share your address with collaborators. To start: channel_create with their address in `members`, then send them the channel_id; to join theirs: channel_join, then channel_wait to listen." : faucet?.ok ? "Faucet request accepted; the balance can take a few seconds to show. Run system_setup again to confirm." : network === "testnet" ? `Automatic faucet failed. Open ${web_faucet} in a browser to request testnet SUI, then run system_setup again.` : `Send SUI to ${address} to pay for gas, then run system_setup again.`;
      return {
        address,
        network,
        balance_sui: mist / MIST_PER_SUI2,
        funded,
        ...faucet ? { faucet } : {},
        web_faucet,
        next_steps
      };
    }
  };
}

// src/logging.ts
import { createHash } from "node:crypto";
import { mkdirSync as mkdirSync3, appendFileSync, existsSync as existsSync3, readFileSync as readFileSync3 } from "node:fs";
import { join as join4 } from "node:path";
var ToolLog = class {
  constructor(dir) {
    this.dir = dir;
    mkdirSync3(dir, { recursive: true });
  }
  dir;
  todayFile() {
    const d = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
    return join4(this.dir, `${d}.jsonl`);
  }
  inputHash(input) {
    return createHash("sha256").update(JSON.stringify(input)).digest("hex").slice(0, 16);
  }
  record(entry) {
    const line = JSON.stringify({ ts: (/* @__PURE__ */ new Date()).toISOString(), ...entry });
    appendFileSync(this.todayFile(), line + "\n", "utf-8");
  }
  tail(limit) {
    const f = this.todayFile();
    if (!existsSync3(f)) return [];
    const lines = readFileSync3(f, "utf-8").trim().split("\n").filter(Boolean);
    return lines.slice(-limit).reverse().map((l) => JSON.parse(l));
  }
};

// src/outbox.ts
import { existsSync as existsSync4, mkdirSync as mkdirSync4, readFileSync as readFileSync4, writeFileSync as writeFileSync3 } from "node:fs";
import { join as join5 } from "node:path";
var Outbox = class {
  file;
  constructor(dir) {
    mkdirSync4(dir, { recursive: true });
    this.file = join5(dir, "outbox.json");
    if (!existsSync4(this.file)) writeFileSync3(this.file, "[]");
  }
  read() {
    return JSON.parse(readFileSync4(this.file, "utf-8"));
  }
  write(items) {
    writeFileSync3(this.file, JSON.stringify(items, null, 2));
  }
  enqueue(item) {
    const items = this.read();
    items.push({ ...item, enqueuedAt: Date.now(), attempts: 0 });
    this.write(items);
  }
  pending() {
    return this.read();
  }
  markDone(id) {
    this.write(this.read().filter((i) => i.id !== id));
  }
  incrementAttempt(id) {
    const items = this.read();
    const found = items.find((i) => i.id === id);
    if (found) {
      found.attempts++;
      this.write(items);
    }
  }
};

// src/init.ts
function initReport(env = process.env) {
  const { config: config2, configFile, created } = bootstrapConfig(env);
  const address = deriveAddress(config2.privateKey);
  const lines = [
    created ? `Generated wallet, config written to ${configFile}` : `Using config ${configFile}`,
    `Address: ${address}`,
    `Network: ${config2.network}`,
    `Transport: ${config2.relayerUrl ? `relayer ${config2.relayerUrl}` : "serverless (Sui + Walrus)"}`,
    "",
    "Next steps:"
  ];
  if (config2.network === "testnet") {
    lines.push(`  1. Fund the wallet: run /agent-stack setup (uses the faucet) or open ${webFaucetUrl(address)}`);
  } else {
    lines.push(`  1. Send SUI to ${address} for gas.`);
  }
  lines.push(
    "  2. Share your address with collaborators so they can invite you.",
    '  3. In Claude Code: /agent-channel new "<topic>" <peer-address>, or /agent-channel join <channel_id>.'
  );
  return lines;
}

// src/cli.ts
async function main() {
  const args = process.argv.slice(2);
  if (args[0] === "init") {
    console.log(initReport().join("\n"));
    return;
  }
  if (args.includes("--health")) {
    try {
      loadConfig();
      console.log(JSON.stringify({ status: "ok" }));
      process.exit(0);
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e);
      console.error(JSON.stringify({ status: "error", message }));
      process.exit(1);
    }
  }
  const config2 = loadConfig();
  const toolLog = new ToolLog(config2.logDir);
  const outbox = new Outbox(path.join(path.dirname(config2.logDir), "outbox"));
  const sdk = getSdk(config2);
  const address = sdk.keypair.toSuiAddress();
  const dispatcher = new Dispatcher(
    toolLog,
    (e) => mapSdkError(e, { address, network: config2.network })
  );
  dispatcher.register(whoamiTool(sdk));
  dispatcher.register(verifyTool(sdk));
  dispatcher.register(createTool(sdk));
  dispatcher.register(membersTool(sdk));
  dispatcher.register(inviteTool(sdk));
  dispatcher.register(kickTool(sdk));
  dispatcher.register(leaveTool(sdk));
  dispatcher.register(sendTool(sdk, outbox));
  dispatcher.register(historyTool(sdk));
  dispatcher.register(joinTool(sdk));
  dispatcher.register(waitTool(sdk));
  dispatcher.register(writeTool(sdk));
  dispatcher.register(readTool(sdk));
  dispatcher.register(debugTool(toolLog));
  dispatcher.register(resendTool(outbox, dispatcher));
  dispatcher.register(healthTool(sdk));
  dispatcher.register(setupTool(sdk));
  await startServer(dispatcher);
}
main().catch((e) => {
  console.error(e);
  process.exit(1);
});
